});

// 测试：游戏状态
test('game status', () => {
  const game = new Game({ seed: 'ORBIT-2049' });

  // 初始状态应该是playing
  assert.strictEqual(game.status, 'playing');

  // 收集所有芯片后应该赢
  game.collected = 3;
  game.player.x = 0; // 假设出口在(0,0)
  game.player.y = 0;
  game.grid[0][0] = 5; // EXIT

  game.move(0, 0); // 移动到出口
  assert.strictEqual(game.status, 'won');
});"}

