'use strict';

// 伪随机数生成器（线性同余法）
class Random {
  constructor(seed) {
    this.seed = seed;
    this.state = seed.hashCode ? seed.hashCode() : seed;
  }

  next() {
    this.state = (this.state * 1664525 + 1013904223) % Math.pow(2, 32);
    return this.state;
  }

  // 返回 [0, max)
  nextInt(max) {
    return this.next() % max;
  }

  // 返回 [min, max)
  nextRange(min, max) {
    return min + (this.next() % (max - min));
  }
}

// 地图元素类型
const TILE_TYPES = {
  EMPTY: 0,
  WALL: 1,
  CHIP: 2,
  SUPPLY: 3,
  ENEMY: 4,
  EXIT: 5
};

// 游戏主类
class Game {
  constructor({ seed = 'ORBIT-2049', width = 18, height = 12 }) {
    this.width = width;
    this.height = height;
    this.seed = seed;
    this.random = new Random(seed.hashCode ? seed.hashCode() : seed);

    // 游戏状态
    this.player = { x: 0, y: 0, hp: 5, energy: 12 };
    this.enemies = [];
    this.chips = [];
    this.collected = 0;
    this.turn = 0;
    this.status = 'playing';

    // 地图网格
    this.grid = Array(this.height).fill().map(() => Array(this.width).fill(TILE_TYPES.EMPTY));

    // 初始化地图
    this._generateMap();
  }

  // 生成地图（保证可达性）
  _generateMap() {
    // 先清空地图
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        this.grid[y][x] = TILE_TYPES.EMPTY;
      }
    }

    // 放置墙（随机但不完全随机）
    const wallCount = Math.floor((this.width * this.height) * 0.2);
    for (let i = 0; i < wallCount; i++) {
      let x, y;
      do {
        x = this.random.nextInt(this.width);
        y = this.random.nextInt(this.height);
      } while (this.grid[y][x] !== TILE_TYPES.EMPTY);
      this.grid[y][x] = TILE_TYPES.WALL;
    }

    // 确保玩家起始位置为空
    let startX, startY;
    do {
      startX = this.random.nextInt(this.width);
      startY = this.random.nextInt(this.height);
    } while (this.grid[startY][startX] !== TILE_TYPES.EMPTY);
    this.player.x = startX;
    this.player.y = startY;

    // 生成芯片（3个）
    for (let i = 0; i < 3; i++) {
      let x, y;
      do {
        x = this.random.nextInt(this.width);
        y = this.random.nextInt(this.height);
      } while (this.grid[y][x] !== TILE_TYPES.EMPTY);
      this.grid[y][x] = TILE_TYPES.CHIP;
      this.chips.push({ x, y });
    }

    // 生成补给
    const supplyCount = 3;
    for (let i = 0; i < supplyCount; i++) {
      let x, y;
      do {
        x = this.random.nextInt(this.width);
        y = this.random.nextInt(this.height);
      } while (this.grid[y][x] !== TILE_TYPES.EMPTY);
      this.grid[y][x] = TILE_TYPES.SUPPLY;
    }

    // 生成敌人
    const enemyCount = 4;
    for (let i = 0; i < enemyCount; i++) {
      let x, y;
      do {
        x = this.random.nextInt(this.width);
        y = this.random.nextInt(this.height);
      } while (this.grid[y][x] !== TILE_TYPES.EMPTY);
      this.grid[y][x] = TILE_TYPES.ENEMY;
      this.enemies.push({ x, y });
    }

    // 生成出口
    let exitX, exitY;
    do {
      exitX = this.random.nextInt(this.width);
      exitY = this.random.nextInt(this.height);
    } while (this.grid[exitY][exitX] !== TILE_TYPES.EMPTY);
    this.grid[exitY][exitX] = TILE_TYPES.EXIT;

    // 简单检查可达性（不保证完全连通，但基本满足）
    if (!this._isReachable(this.player.x, this.player.y, exitX, exitY)) {
      // 重置地图生成逻辑（简化处理）
      this._generateMap();
    }
  }

  // 简单的可达性检查（广度优先搜索）
  _isReachable(startX, startY, endX, endY) {
    const visited = Array(this.height).fill().map(() => Array(this.width).fill(false));
    const queue = [[startX, startY]];
    visited[startY][startX] = true;

    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    while (queue.length > 0) {
      const [x, y] = queue.shift();

      if (x === endX && y === endY) {
        return true;
      }

      for (const [dx, dy] of directions) {
        const nx = x + dx;
        const ny = y + dy;

        if (nx >= 0 && nx < this.width && ny >= 0 && ny < this.height &&
            !visited[ny][nx] && this.grid[ny][nx] !== TILE_TYPES.WALL) {
          visited[ny][nx] = true;
          queue.push([nx, ny]);
        }
      }
    }

    return false;
  }

  // 移动玩家
  move(dx, dy) {
    if (this.status !== 'playing') return false;

    const newX = this.player.x + dx;
    const newY = this.player.y + dy;

    // 检查边界
    if (newX < 0 || newX >= this.width || newY < 0 || newY >= this.height) {
      return false;
    }

    // 检查是否是墙
    if (this.grid[newY][newX] === TILE_TYPES.WALL) {
      return false;
    }

    // 扣除能量
    if (this.player.energy <= 0) {
      return false;
    }
    this.player.energy--;

    // 移动玩家
    this.player.x = newX;
    this.player.y = newY;

    // 检查是否收集芯片
    const chipIndex = this.chips.findIndex(chip => chip.x === newX && chip.y === newY);
    if (chipIndex !== -1) {
      this.chips.splice(chipIndex, 1);
      this.collected++;
    }

    // 检查是否获得补给
    if (this.grid[newY][newX] === TILE_TYPES.SUPPLY) {
      this.player.energy += 5;
      this.grid[newY][newX] = TILE_TYPES.EMPTY;
    }

    // 检查是否到达出口
    if (this.grid[newY][newX] === TILE_TYPES.EXIT) {
      if (this.collected >= 3) {
        this.status = 'won';
      }
    }

    // 敌人行动
    this._enemyAction();

    // 增加回合数
    this.turn++;

    return true;
  }

  // 等待恢复能量
  wait() {
    if (this.status !== 'playing') return false;

    this.player.energy = Math.min(12, this.player.energy + 1);
    this._enemyAction();
    this.turn++;
    return true;
  }

  // 敌人行动
  _enemyAction() {
    const damageDealt = new Set(); // 避免同一回合重复伤害

    for (let i = 0; i < this.enemies.length; i++) {
      const enemy = this.enemies[i];

      // 简单的AI：向玩家移动
      const dx = this.player.x - enemy.x;
      const dy = this.player.y - enemy.y;

      let moveX = 0;
      let moveY = 0;

      if (Math.abs(dx) > Math.abs(dy)) {
        moveX = dx > 0 ? 1 : -1;
      } else {
        moveY = dy > 0 ? 1 : -1;
      }

      const newX = enemy.x + moveX;
      const newY = enemy.y + moveY;

      // 检查边界和墙
      if (newX >= 0 && newX < this.width && newY >= 0 && newY < this.height &&
          this.grid[newY][newX] !== TILE_TYPES.WALL) {
        // 检查是否撞到玩家
        if (newX === this.player.x && newY === this.player.y) {
          if (!damageDealt.has(`${newX},${newY}`)) {
            damageDealt.add(`${newX},${newY}`);
            this.player.hp--;
            if (this.player.hp <= 0) {
              this.status = 'lost';
            }
          }
        } else {
          // 移动敌人
          enemy.x = newX;
          enemy.y = newY;
        }
      }
    }
  }

  // 序列化游戏状态
  serialize() {
    return JSON.stringify({
      seed: this.seed,
      player: this.player,
      enemies: this.enemies,
      chips: this.chips,
      collected: this.collected,
      turn: this.turn,
      status: this.status,
      grid: this.grid,
      randomState: this.random.state
    });
  }

  // 从JSON恢复游戏状态
  static fromJSON(jsonString) {
    const data = JSON.parse(jsonString);

    const game = new Game({ seed: data.seed, width: data.grid[0].length, height: data.grid.length });
    game.player = data.player;
    game.enemies = data.enemies;
    game.chips = data.chips;
    game.collected = data.collected;
    game.turn = data.turn;
    game.status = data.status;
    game.grid = data.grid;
    game.random.state = data.randomState;

    return game;
  }
}

// 字符串哈希函数
String.prototype.hashCode = function() {
  let hash = 0;
  for (let i = 0; i < this.length; i++) {
    const char = this.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // 转换为32位整数
  }
  return hash;
};

// 导出模块（Node.js）
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { Game };
}

// 导入游戏引擎
const { Game } = require('./engine.cjs');

// 游戏状态
let game = null;
let canvas = null;
let ctx = null;
let tile_size = 32;
let view_radius = 3;

// 初始化游戏
function initGame(seed = 'ORBIT-2049') {
  game = new Game({ seed: seed });
  updateUI();
  drawGame();
}

// 更新UI状态显示
function updateUI() {
  if (!game) return;

  document.getElementById('hp').textContent = game.player.hp;
  document.getElementById('energy').textContent = game.player.energy;
  document.getElementById('chips').textContent = game.collected;
  document.getElementById('turn').textContent = game.turn;
}

// 绘制游戏画面
function drawGame() {
  if (!game || !canvas || !ctx) return;

  const width = game.width;
  const height = game.height;

  // 清除画布
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // 计算视野中心
  const center_x = game.player.x;
  const center_y = game.player.y;

  // 绘制地图
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      // 检查是否在视野范围内
      const dx = Math.abs(x - center_x);
      const dy = Math.abs(y - center_y);
      const in_view = (dx <= view_radius && dy <= view_radius);

      // 绘制格子
      const screen_x = (x - center_x + view_radius) * tile_size;
      const screen_y = (y - center_y + view_radius) * tile_size;

      if (in_view) {
        // 在视野内绘制
        const tile_type = game.grid[y][x];
        switch (tile_type) {
          case 0: // EMPTY
            ctx.fillStyle = '#121226';
            break;
          case 1: // WALL
            ctx.fillStyle = '#4a4a6a';
            break;
          case 2: // CHIP
            ctx.fillStyle = '#4fc3f7';
            break;
          case 3: // SUPPLY
            ctx.fillStyle = '#ff9800';
            break;
          case 4: // ENEMY
            ctx.fillStyle = '#f44336';
            break;
          case 5: // EXIT
            ctx.fillStyle = '#8bc34a';
            break;
        }
        ctx.fillRect(screen_x, screen_y, tile_size, tile_size);
      } else {
        // 在视野外绘制迷雾
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        ctx.fillRect(screen_x, screen_y, tile_size, tile_size);
      }
    }
  }

  // 绘制玩家
  const player_screen_x = (game.player.x - center_x + view_radius) * tile_size;
  const player_screen_y = (game.player.y - center_y + view_radius) * tile_size;
  ctx.fillStyle = '#2196f3';
  ctx.fillRect(player_screen_x, player_screen_y, tile_size, tile_size);
}

// 处理移动
function movePlayer(dx, dy) {
  if (!game || game.status !== 'playing') return false;

  const success = game.move(dx, dy);
  updateUI();
  drawGame();
  return success;
}

// 等待动作
function waitAction() {
  if (!game || game.status !== 'playing') return false;

  game.wait();
  updateUI();
  drawGame();
  return true;
}

// 导出回放
function exportReplay() {
  if (!game) return;

  const replayData = {
    seed: game.seed,
    actions: []
  };

  // 这里应该记录所有动作，为简化起见我们只记录当前状态
  alert('导出功能需要完整实现动作序列记录，当前仅显示提示');
}

// 导入回放
function importReplay() {
  alert('导入功能需要完整实现，当前仅显示提示');
}

// 保存到槽位
function saveToSlot(slot) {
  if (!game) return;

  try {
    const data = game.serialize();
    localStorage.setItem(`game_save_${slot}`, data);
    alert(`已保存到槽位${slot}`);
  } catch (e) {
    alert('保存失败');
  }
}

// 从槽位读取
function loadFromSlot(slot) {
  try {
    const data = localStorage.getItem(`game_save_${slot}`);
    if (data) {
      game = Game.fromJSON(data);
      updateUI();
      drawGame();
      alert(`已从槽位${slot}读取`);
    } else {
      alert('槽位无数据');
    }
  } catch (e) {
    alert('读取失败');
  }
}

// 事件处理
document.addEventListener('DOMContentLoaded', () => {
  canvas = document.getElementById('gameCanvas');
  ctx = canvas.getContext('2d');

  // 初始化游戏
  initGame('ORBIT-2049');

  // 键盘控制
  document.addEventListener('keydown', (e) => {
    switch (e.key) {
      case 'ArrowUp':
      case 'w':
      case 'W':
        movePlayer(0, -1);
        break;
      case 'ArrowDown':
      case 's':
      case 'S':
        movePlayer(0, 1);
        break;
      case 'ArrowLeft':
      case 'a':
      case 'A':
        movePlayer(-1, 0);
        break;
      case 'ArrowRight':
      case 'd':
      case 'D':
        movePlayer(1, 0);
        break;
      case 'z':
      case 'Z':
        waitAction();
        break;
    }
  });

  // 按钮控制
  document.getElementById('resetBtn').addEventListener('click', () => {
    initGame('ORBIT-2049');
  });

  document.getElementById('loadSeedBtn').addEventListener('click', () => {
    const seed = document.getElementById('seedInput').value;
    if (seed) {
      initGame(seed);
    }
  });

  document.getElementById('saveSlot1').addEventListener('click', () => {
    saveToSlot(1);
  });

  document.getElementById('loadSlot1').addEventListener('click', () => {
    loadFromSlot(1);
  });

  document.getElementById('exportReplay').addEventListener('click', exportReplay);
  document.getElementById('importReplay').addEventListener('click', importReplay);

  // 触屏控制
  document.querySelectorAll('.dir-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const [dx, dy] = e.target.dataset.dir.split(',').map(Number);
      movePlayer(dx, dy);
    });
  });

  document.getElementById('waitBtn').addEventListener('click', waitAction);

  // 绘制初始画面
  drawGame();
});
